shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --crimson: #8f241e;
    --crimson-soft: rgba(143, 36, 30, 0.08);
    --navy-bg: #0f1d2b;
    --navy-card: #16293d;
    --navy-line: #28415a;
    --gold: #d4a359;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-behavior: smooth;
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif-cn);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.75;
  }

  /* Top Progress Bar */
  .progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: var(--accent);
    width: 0%;
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-monogram {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-decoration: none;
  }

  .masthead-divider {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }

  .section-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
  }

  .edition-code {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
    letter-spacing: 0.05em;
  }

  /* Bilingual Toggle */
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
    gap: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.74rem;
    font-weight: 600;
    padding: 0.28rem 0.72rem;
    border-radius: 999px;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
    letter-spacing: 0.03em;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .page-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0 1.5rem 5rem;
  }

  /* Hero Header */
  .article-hero {
    padding: 3.25rem 0 2.5rem;
    border-bottom: 3px double var(--ink);
    margin-bottom: 2.75rem;
  }

  .hero-kicker-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .kicker-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-family: var(--font-sans);
    font-size: 0.76rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--crimson);
    background: var(--crimson-soft);
    border: 1px solid rgba(143, 36, 30, 0.22);
    padding: 0.3rem 0.75rem;
  }

  .kicker-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--crimson);
  }

  .docket-meta {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    letter-spacing: 0.04em;
  }

  .headline {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2rem, 4.1vw, 3.35rem);
    line-height: 1.24;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.5rem;
    max-width: 980px;
  }

  :host([lang="en"]) .headline {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -0.02em;
  }

  /* Hero Executive Strip */
  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.84rem;
    color: var(--muted);
  }

  .byline-block {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.65rem;
  }

  .byline-author {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .meta-sep {
    color: var(--line-strong);
  }

  .court-stamp {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--ink);
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 0.25rem 0.65rem;
  }

  /* Case Snapshot Grid (Editorial Briefing Bar) */
  .briefing-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-bottom: 3rem;
  }

  .brief-cell {
    background: var(--paper-card);
    padding: 1.15rem 1.25rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .brief-label {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--muted);
    margin-bottom: 0.45rem;
  }

  .brief-val {
    font-family: var(--font-serif-cn);
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.35;
  }

  :host([lang="en"]) .brief-val {
    font-family: var(--font-serif-en);
  }

  .brief-sub {
    font-family: var(--font-sans);
    font-size: 0.74rem;
    color: var(--muted);
    margin-top: 0.35rem;
  }

  /* Asymmetric Editorial Grid */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(280px, 4.5fr);
    gap: 3.25rem;
    align-items: start;
    margin-bottom: 3.25rem;
  }

  .narrative-col {
    min-width: 0;
  }

  .rail-col {
    min-width: 0;
    position: sticky;
    top: 4.5rem;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Section Headers (Editorial Dividers) */
  .act-header {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    margin: 2.5rem 0 1.35rem;
    padding-bottom: 0.55rem;
    border-bottom: 1px solid var(--ink);
  }

  .act-header:first-child {
    margin-top: 0;
  }

  .act-num {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.18rem 0.5rem;
    letter-spacing: 0.08em;
  }

  .act-title {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.11em;
    color: var(--ink);
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.45rem;
    text-align: left;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
  }

  /* Lead Paragraph Styling (No ::first-letter on Chinese) */
  .prose-lead {
    font-size: 1.26rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.75;
    padding-left: 1.15rem;
    border-left: 4px solid var(--crimson);
    margin-bottom: 1.75rem;
  }

  :host([lang="en"]) .prose-lead {
    font-size: 1.24rem;
    line-height: 1.65;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 2px;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
  }

  /* Judicial Order Callout Card (Right Rail) */
  .docket-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 4px solid var(--crimson);
    padding: 1.5rem;
  }

  .docket-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 0.75rem;
    margin-bottom: 1rem;
    border-bottom: 1px dashed var(--line-strong);
  }

  .docket-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--crimson);
  }

  .docket-pages {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
  }

  .pull-quote {
    margin: 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.08rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.85rem;
  }

  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--font-serif-en);
    font-style: italic;
    font-size: 1.06rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-sans);
    font-size: 0.76rem;
    color: var(--muted);
    display: flex;
    align-items: center;
    gap: 0.4rem;
  }

  .pull-quote .quote-attrib::before {
    content: "—";
    color: var(--accent);
    font-weight: 700;
  }

  .docket-specs {
    margin-top: 1.15rem;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
    font-family: var(--font-sans);
    font-size: 0.76rem;
  }

  .spec-item strong {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.66rem;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 0.15rem;
  }

  .spec-item span {
    color: var(--ink);
    font-weight: 600;
  }

  /* Timeline / Sunday Collision Widget */
  .collision-card {
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 1.5rem;
    border: 1px solid var(--navy-line);
  }

  .collision-kicker {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--gold);
    margin-bottom: 0.35rem;
  }

  .collision-title {
    font-family: var(--font-serif-cn);
    font-size: 1.1rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 1rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--navy-line);
  }

  :host([lang="en"]) .collision-title {
    font-family: var(--font-serif-en);
  }

  .timeline-list {
    list-style: none;
    position: relative;
    padding-left: 1.1rem;
    border-left: 1px solid var(--navy-line);
  }

  .timeline-item {
    position: relative;
    margin-bottom: 1.1rem;
  }

  .timeline-item:last-child {
    margin-bottom: 0;
  }

  .timeline-dot {
    position: absolute;
    left: -1.42rem;
    top: 0.32rem;
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: var(--gold);
    border: 2px solid var(--navy-bg);
  }

  .timeline-time {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--gold);
    letter-spacing: 0.05em;
    display: block;
    margin-bottom: 0.15rem;
  }

  .timeline-desc {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    line-height: 1.5;
    color: #d8d3c8;
  }

  /* Full-Width Forensic Funding Architecture Diagram */
  .forensic-band {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 2px solid var(--ink);
    padding: 2.5rem 2rem;
    margin: 3rem 0;
  }

  .forensic-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.75rem;
  }

  .forensic-eyebrow {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.35rem;
  }

  .forensic-title {
    font-family: var(--font-serif-cn);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  :host([lang="en"]) .forensic-title {
    font-family: var(--font-serif-en);
  }

  .forensic-legend {
    display: flex;
    gap: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
  }

  .legend-item {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
  }

  .legend-swatch {
    width: 10px;
    height: 10px;
    display: inline-block;
  }

  .svg-container {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line-strong);
    padding: 0.5rem;
  }

  /* Split Sentence Feature Box (p7 & p10) */
  .funding-split-pair {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.25rem;
    margin-bottom: 1.5rem;
  }

  .split-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.25rem 1.35rem;
    position: relative;
  }

  .split-card.flagged {
    border-left: 4px solid var(--accent);
    background: #f6f0e4;
  }

  .split-card-tag {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.5rem;
    display: block;
  }

  .split-card .prose-p {
    margin-bottom: 0;
    font-size: 1.04rem;
  }

  /* Climactic Verdict Blockquote (p10.s2) */
  .verdict-quote-box {
    margin: 2rem 0 2.25rem;
    padding: 2rem 2.25rem;
    background: var(--navy-bg);
    color: #faf8f4;
    border-left: 5px solid var(--gold);
    position: relative;
  }

  .verdict-quote-header {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--gold);
    margin-bottom: 0.85rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .verdict-quote {
    font-family: var(--font-serif-cn);
    font-size: 1.2rem;
    line-height: 1.75;
    font-weight: 600;
    color: #ffffff;
  }

  :host([lang="en"]) .verdict-quote {
    font-family: var(--font-serif-en);
    font-size: 1.22rem;
    line-height: 1.6;
  }

  /* Final Resolution Card (p11) */
  .pivot-resolution-box {
    background: var(--paper-card);
    border: 1px solid var(--ink);
    padding: 1.75rem 2rem;
    margin-top: 2rem;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 1.5rem;
    align-items: center;
  }

  .pivot-badge {
    background: var(--ink);
    color: var(--paper);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    padding: 0.85rem 1rem;
    text-align: center;
    letter-spacing: 0.06em;
    line-height: 1.4;
    text-transform: uppercase;
  }

  .pivot-resolution-box .prose-p {
    margin-bottom: 0;
    font-weight: 600;
    color: var(--ink);
  }

  /* Plaintiffs Dossier Card (Rail) */
  .dossier-card {
    background: var(--paper);
    border: 1px solid var(--line-strong);
    padding: 1.4rem;
  }

  .dossier-title {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--ink);
    padding-bottom: 0.6rem;
    margin-bottom: 1rem;
    border-bottom: 2px solid var(--ink);
  }

  .party-row {
    padding: 0.75rem 0;
    border-bottom: 1px solid var(--line);
  }

  .party-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .party-role {
    font-family: var(--font-mono);
    font-size: 0.66rem;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--accent);
    display: block;
    margin-bottom: 0.2rem;
  }

  .party-name {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: 0.96rem;
    color: var(--ink);
  }

  :host([lang="en"]) .party-name {
    font-family: var(--font-serif-en);
  }

  .party-desc {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
    margin-top: 0.2rem;
    line-height: 1.45;
  }

  /* Footer */
  .article-footer {
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .briefing-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2.25rem;
    }
    .rail-col {
      position: static;
    }
    .funding-split-pair {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 560px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .page-shell {
      padding: 0 1rem 3.5rem;
    }
    .briefing-strip {
      grid-template-columns: 1fr;
    }
    .forensic-band {
      padding: 1.5rem 1rem;
      margin: 2rem 0;
    }
    .verdict-quote-box {
      padding: 1.35rem 1.25rem;
    }
    .pivot-resolution-box {
      grid-template-columns: 1fr;
      gap: 1rem;
      padding: 1.25rem;
    }
    .edition-code {
      display: none;
    }
  }
